changeSet.sql:
DO $$
DECLARE
  found text := '';
  counted record;
BEGIN
  SELECT count(*) FILTER (WHERE NOT (native_recipient IS NULL OR jsonb_typeof(native_recipient) = 'object')) AS n1,
         count(*) FILTER (WHERE NOT (payload IS NULL OR jsonb_typeof(payload) = 'object')) AS n2
  INTO counted FROM agent_action;
  IF counted.n1 > 0 THEN found := found || format(E'\n  %s.%s: %s', 'agent_action', 'native_recipient', counted.n1); END IF;
  IF counted.n2 > 0 THEN found := found || format(E'\n  %s.%s: %s', 'agent_action', 'payload', counted.n2); END IF;
  IF found <> '' THEN
    RAISE EXCEPTION E'The upgrade stopped before it checks the stored rows of agent_action. Each column below holds rows with a JSON value that the server cannot read, followed by their number:%\nCorrect or delete these rows, then start the upgrade again. The migration guide for this release gives the query that lists them.', found;
  END IF;
END $$

